const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();
app.use(express.json());

app.put('/api/vehicles/:vin', async (req, res) => {
  if (!req.user || !req.user.companyId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { assignedDriver, status } = req.body;

  // Use updateMany to safely enforce non-unique companyId condition
  const updateResult = await prisma.fleetVehicle.updateMany({
    where: {
      vin: req.params.vin,
      companyId: req.user.companyId
    },
    data: { assignedDriver, status }
  });

  if (updateResult.count === 0) {
    return res.status(404).json({ error: 'Vehicle not found or does not belong to your company' });
  }

  res.json({ success: true, updatedCount: updateResult.count });
});

app.listen(3035);
